package org.jfree.data.time;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Calendar;
import java.util.Collection;
import java.util.Collections;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.List;
import java.util.TimeZone;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class TimeSeries_createCopy_TriageGen0Test {

    private TimeSeries series;
    private RegularTimePeriod p1;
    private RegularTimePeriod p2;
    private RegularTimePeriod p3;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");
        p1 = new Second(new GregorianCalendar(2023, 0, 1, 10, 0, 0));
        p2 = new Second(new GregorianCalendar(2023, 0, 1, 10, 0, 10));
        p3 = new Second(new GregorianCalendar(2023, 0, 1, 10, 0, 20));

        series.add(p1, 1.0);
        series.add(p2, 2.0);
        series.add(p3, 3.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyNullStart() throws CloneNotSupportedException {
        series.createCopy(null, p2);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyNullEnd() throws CloneNotSupportedException {
        series.createCopy(p1, null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyStartAfterEnd() throws CloneNotSupportedException {
        series.createCopy(p2, p1);
    }

    @Test
    public void testCreateCopyExactRange() throws CloneNotSupportedException {
        TimeSeries copy = series.createCopy(p1, p3);
        assertEquals(3, copy.getItemCount());
        assertEquals(1.0, copy.getValue(0).doubleValue(), 0.001);
        assertEquals(3.0, copy.getValue(2).doubleValue(), 0.001);
    }

    @Test
    public void testCreateCopyPartialRange() throws CloneNotSupportedException {
        // p2 is at index 1. end is p2. 
        // getIndex(p2) returns 1. endIndex is 1.
        // createCopy(1, 1) should return items from index 1 to 1.
        TimeSeries copy = series.createCopy(p2, p2);
        assertEquals(1, copy.getItemCount());
        assertEquals(2.0, copy.getValue(0).doubleValue(), 0.001);
    }

    @Test
    public void testCreateCopyRangeWithMissingEnd() throws CloneNotSupportedException {
        // Create a period that is not in the series but falls between p2 and p3
        RegularTimePeriod mid = new Second(new GregorianCalendar(2023, 0, 1, 10, 0, 15));
        // getIndex(mid) will return -2 (representing index 1 is the first item after mid)
        // endIndex = -(-2 + 1) - 1 = 1 - 1 = 0? No. 
        // Let's trace: getIndex(mid) -> returns -2. 
        // endIndex = -(-2 + 1) = 1. 
        // endIndex = 1 - 1 = 0.
        // Actually, if mid is between index 1 and 2:
        // getIndex(mid) returns -3 (the index of the first element AFTER mid, which is index 2)
        // endIndex = -(-3 + 1) = 2.
        // endIndex = 2 - 1 = 1.
        // So range is [startIndex, 1].

        TimeSeries copy = series.createCopy(p1, mid);
        // startIndex for p1 is 0.
        // endIndex for mid: getIndex(mid) returns -3. endIndex = -(-3+1)-1 = 1.
        // Result should be items at index 0 and 1.
        assertEquals(2, copy.getItemCount());
        assertEquals(1.0, copy.getValue(0).doubleValue(), 0.001);
        assertEquals(2.0, copy.getValue(1).doubleValue(), 0.001);
    }

    @Test
    public void testCreateCopyEmptyRangeStartAfterLast() throws CloneNotSupportedException {
        RegularTimePeriod afterLast = new Second(new GregorianCalendar(2023, 0, 1, 10, 1, 0));
        // getIndex(afterLast) returns -4 (index 3 is first after)
        // startIndex = -(-4 + 1) = 3. 
        // startIndex == series.data.size() (3), so emptyRange = true.
        TimeSeries copy = series.createCopy(afterLast, afterLast);
        assertEquals(0, copy.getItemCount());
    }

    @Test
    public void testCreateCopyEmptyRangeEndBeforeFirst() throws CloneNotSupportedException {
        RegularTimePeriod beforeFirst = new Second(new GregorianCalendar(2023, 0, 1, 0, 0, 0));
        // getIndex(beforeFirst) returns -1 (index 0 is first after)
        // endIndex = -(-1 + 1) = 0.
        // endIndex = 0 - 1 = -1.
        // endIndex < 0 -> emptyRange = true.
        TimeSeries copy = series.createCopy(beforeFirst, beforeFirst);
        assertEquals(0, copy.getItemCount());
    }

    @Test
    public void testCreateCopyEmptyRangeStartEqualsEndButEmpty() throws CloneNotSupportedException {
        // Using a period that exists but creates an empty range logic if possible
        // If start and end are the same and not in series
        RegularTimePeriod p4 = new Second(new GregorianCalendar(2023, 0, 1, 10, 0, 15));
        // getIndex(p4) is -3. startIndex = 2.
        // getIndex(p4) is -3. endIndex = 1.
        // But start.compareTo(end) is 0, so it passes.
        // However, the code logic: startIndex = 2, endIndex = 1. 
        // This would trigger the createCopy(int, int) which might throw error or return empty.
        // The current implementation relies on start.compareTo(end) <= 0.
        // If startIndex > endIndex, the behavior depends on the int-based createCopy.
    }
}
